import { View, Text, TextInput, StyleSheet } from "react-native";
import { useState, useEffect } from "react";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "p1", name: "Чихэвч" }, { id: "p2", name: "Гар цаг" }, { id: "p3", name: "Нарны шил" },
  { id: "p4", name: "Цүнх" }, { id: "p5", name: "Ном" }, { id: "p6", name: "Гутал" },
];
const fakeApi = (query) => new Promise((res) => setTimeout(() => res(
  PRODUCTS.filter((p) => p.name.toLowerCase().includes(query.toLowerCase()))
), 200));

function App() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState(PRODUCTS);

  useEffect(() => {
    let alive = true;
    fakeApi(query).then((data) => { if (alive) setResults(data); });
    return () => { alive = false; };
  }, []); // энд бичнэ үү: query өөрчлөгдөх бүрт дахин хайхын тулд хамаарлыг нэм

  return (
    <View style={styles.s}>
      <TextInput
        nativeID="q"
        style={styles.input}
        placeholder="Бараа хайх..."
        value={query}
        onChangeText={setQuery}
      />
      {results.map((it) => <Text key={it.id} testID="row" style={styles.row}>{it.name}</Text>)}
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 16, gap: 8 },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 12, fontSize: 16 },
  row: { fontSize: 16, paddingVertical: 10, borderBottomWidth: 1, borderColor: "#e2e8f0" },
});

registerRootComponent(App);

